/* Extended learning views use the same state, routes and storage as app.js. */
let readingMode='cn',storyLimit=12;
let wordIndex=new Map(BUILTIN_WORDS.map(w=>[w.id,w]));
function refreshWordIndex(){wordIndex=new Map(BUILTIN_WORDS.map(w=>[w.id,w]));}
const rawCleanState=cleanState;
cleanState=function(raw){
  const s=rawCleanState(raw);
  s.bookmarks=Array.isArray(raw?.bookmarks)?raw.bookmarks.filter(isKnownWordsceneStory):[];
  s.mistakes=Object.fromEntries(Object.entries(raw?.mistakes||{}).filter(([id,n])=>getWordSafe(id,s)&&Number.isInteger(n)&&n>0));
  s.preferences={...s.preferences,size:[18,20,22,24].includes(raw?.preferences?.size)?raw.preferences.size:20,night:Boolean(raw?.preferences?.night),rate:[.7,.85,1,1.15].includes(raw?.preferences?.rate)?raw.preferences.rate:.85};
  s.words=Object.fromEntries(Object.entries(s.words).filter(([,p])=>/^\d{4}-\d{2}-\d{2}$/.test(p.due)));
  return s;
};
function getWordSafe(id,s){return BUILTIN_INDEX.has(id)||wordIndex.has(id)||s.custom.some(w=>w.id===id);}
// Recover additional fields omitted by the previous renderer's sanitization.
try{state=cleanState(JSON.parse(localStorage.getItem(KEY)||localStorage.getItem('wordscene-v1'))||state);}catch{state=cleanState(state);}
const oldRecord=record;
record=function(id,correct){if(!getWord(id))return;if(!correct)state.mistakes[id]=(state.mistakes[id]||0)+1;const old=state.words[id];if(correct&&old?.last===today()&&old.stage>0){state.activity[today()]=[...new Set([...(state.activity[today()]||[]),id])];save();return;}oldRecord(id,correct);};
function applyPreferences(){document.body.classList.toggle('night',state.preferences.night);document.documentElement.style.setProperty('--reading-size',state.preferences.size+'px');}
const oldStats=stats;
stats=function(){return oldStats().replace('词已掌握','词已学习').replace('重点词 + 六级扩展词库','完整参考词表 + 故事补充词');};
function coveragePanel(){
  const referencePercent=((COVERAGE.reference||0)?(COVERAGE.contextual/COVERAGE.reference*100):0).toFixed(1);
  const allPercent=((COVERAGE.total||0)?(COVERAGE.coveredTotal/COVERAGE.total*100):0).toFixed(1);
  return `<section class="coverage-panel"><div><strong>${COVERAGE.coveredTotal.toLocaleString()} / ${COVERAGE.total.toLocaleString()} 词</strong><p>已有故事语境 · 覆盖率 ${allPercent}%<br>参考词表 ${COVERAGE.contextual.toLocaleString()} / ${COVERAGE.reference.toLocaleString()} 词（${referencePercent}%）</p></div><div><strong>${STORIES.length} 篇短篇</strong><p>修仙 ${STORIES.filter(s=>s.category==='修仙志').length} 篇 · 悬疑 ${STORIES.filter(s=>s.category==='悬疑案').length} 篇<br>每个词都按故事中的实际出现核对</p></div><a class="button secondary compact" href="#units">按单元学习全部词 →</a></section>`;
}
const oldLibrary=library;
library=function(){oldLibrary();if(!main)return;const hero=main.querySelector('.hero');if(!hero)return;const title=hero.querySelector('h1'),copy=hero.querySelector('p'),actions=hero.querySelector('.hero-actions'),statsStrip=main.querySelector('.stats-strip');if(title)title.innerHTML='先入故事，<br>再让单词<em>有处可寻。</em>';if(copy)copy.innerHTML='先读懂中文里的山雨、灯影与人物选择。<br>再看英文如何表达，最后关掉提示，试着把它想起来。';if(actions)actions.insertAdjacentHTML('beforeend','<button class="text-link" data-action="random-story">随机一篇 ↗</button>');if(statsStrip)statsStrip.insertAdjacentHTML('afterend',coveragePanel());};
storyCard=function(s){const known=s.words.filter(w=>state.words[w.id]?.stage>0).length,excerpt=s.cn[0].replace(/\[\[[^|]+\|([^\]]+)\]\]/g,'$1');return `<a class="story-card" href="#story/${s.id}"><div class="cover" style="--cover:${s.color};--cover-ink:#52635f"><div><div class="cover-type">${s.category} · ${s.tag}</div><div class="cover-title">${esc(s.title)}</div></div><div class="cover-symbol">${s.symbol}</div><span class="cover-no">CHAPTER ${String(s.number).padStart(2,'0')}</span></div><div class="card-body"><div class="card-tags"><span class="tag">${s.category}</span><span>${state.completed.includes(s.id)?'✓ 已读':'未读'} · ${s.words.length} 词</span></div><h3>${esc(s.title)}</h3><p>${esc(excerpt)}</p><div class="card-bottom"><span>${known?`${known}/${s.words.length} 词已学习`:s.mood}</span><span>${state.bookmarks.includes(s.id)?'★ 书签':'阅读'} ↗</span></div></div></a>`;};
renderCards=function(){const list=filteredStories(),count=document.getElementById('story-count'),grid=document.getElementById('story-grid');if(!count||!grid)return;count.textContent=`${list.length} 篇短篇 · ${category==='全部'?'修仙 / 悬疑':category}`;grid.innerHTML=list.length?list.slice(0,storyLimit).map(storyCard).join(''):'<div class="empty-state"><h2>没有匹配的故事</h2><button class="button secondary" data-action="clear-search">清除筛选</button></div>';document.getElementById('more-stories')?.remove();if(list.length>storyLimit)grid.insertAdjacentHTML('afterend','<button id="more-stories" class="button secondary load-more" data-action="more-stories">再显示 12 篇</button>');};
formatEnglish=function(text){return text.split(/(\[\[.*?\]\])/g).map(part=>{if(!part.startsWith('[['))return esc(part);const [id,surface]=part.slice(2,-2).split('|'),w=getWord(id);return w?`<button class="word-inline" data-word="${esc(id)}">${esc(surface||id)}</button>`:esc(surface||id);}).join('');};
function formatChinese(text){return text.split(/(\[\[.*?\]\])/g).map(p=>{if(!p.startsWith('[['))return esc(p);const [id,label]=p.slice(2,-2).split('|');return readingMode==='cn'?esc(label||id):`<button class="cn-word" data-word="${esc(id)}" title="查看对应英文">${esc(label||id)}</button>`;}).join('');}
function readerTools(){return `<div class="reading-tools"><label>字号 <select id="reading-size">${[18,20,22,24].map(n=>`<option value="${n}" ${state.preferences.size===n?'selected':''}>${n}px</option>`).join('')}</select></label><label>语速 <select id="speech-rate">${[.7,.85,1,1.15].map(n=>`<option value="${n}" ${state.preferences.rate===n?'selected':''}>${n}×</option>`).join('')}</select></label><button class="button secondary compact" data-action="night">${state.preferences.night?'日间纸张':'夜间阅读'}</button></div>`;}
reader=function(id){const s=getStory(id);if(!s){main.innerHTML='<div class="empty-state"><h2>章节不存在</h2><a class="button" href="#library">回书架</a></div>';return;}state.lastStory=s.id;save();const sequence=STORIES.filter(x=>x.category===s.category),at=sequence.indexOf(s),prev=sequence[at-1],next=sequence[at+1];main.innerHTML=`<div class="reader-top"><a class="back-link" href="#library">← 回到故事书架</a><div class="reader-controls"><button class="button secondary compact" data-action="bookmark" data-id="${s.id}">${state.bookmarks.includes(s.id)?'★ 已加书签':'☆ 加书签'}</button><button class="button secondary compact" data-action="read-aloud">▷ 朗读英文 / 停止</button><button class="button secondary compact" data-action="focus">${document.body.classList.contains('focus-mode')?'退出专注':'专注阅读'}</button></div></div><div class="study-steps" aria-label="阅读步骤">${[['cn','① 中文沉浸'],['parallel','② 中英对照'],['en','③ 英文回忆']].map(([mode,label])=>`<button data-reading="${mode}" class="${readingMode===mode?'active':''}" aria-pressed="${readingMode===mode}">${label}</button>`).join('')}<button data-action="story-quiz" data-story="${s.id}">④ 章节测验 →</button></div>${readerTools()}<div class="reader-layout"><article class="reader-paper"><div class="eyebrow">${s.category} / ${s.tag} · ${String(s.number).padStart(2,'0')}</div><h1>${esc(s.title)}</h1><div class="practice-label">以下为原创 CET-style 仿真模拟训练。</div><div class="reader-meta">${s.words.length} 个语境重点词 · ${readingMode==='cn'?'先看懂故事，英文暂时收起':readingMode==='parallel'?'中文在前，英文紧随其后':'试着不依赖中文，回忆完整画面'}</div>${s.cn.map((cn,i)=>`<section class="scene-block"><div class="scene-number">${String(i+1).padStart(2,'0')}</div>${readingMode!=='en'?`<p class="reader-paragraph chinese-first">${formatChinese(cn)}</p>`:''}${readingMode!=='cn'?`<p class="translation english-second" lang="en">${formatEnglish(s.en[i])}</p>`:''}</section>`).join('')}<div class="reader-end"><p>回想人物做了什么决定，哪些线索改变了判断？把场景想起来，再试着说出英文。</p><div class="hero-actions"><button class="button" data-action="story-quiz" data-story="${s.id}">开始本章回忆 →</button><button class="text-link" data-action="complete-story" data-story="${s.id}">${state.completed.includes(s.id)?'✓ 已读':'标记读完'}</button></div><div class="chapter-nav">${prev?`<a href="#story/${prev.id}">← ${esc(prev.title)}</a>`:'<span></span>'}${next?`<a href="#story/${next.id}">${esc(next.title)} →</a>`:'<a href="#library">读完本卷，回到书架 →</a>'}</div></div></article><aside class="reader-aside"><h2>${readingMode==='cn'?'先让画面留下来':'本章词签'}</h2>${readingMode==='cn'?'<p>这一步只读中文。读完后切换「中英对照」，点击重点词查看语境义与例句。</p><button class="button secondary compact" data-reading="parallel">读懂了，展开英文 →</button>':`<div class="words">${s.words.map(w=>`<div class="word-row"><button data-word="${esc(w.id)}">${esc(w.word)}<small>${esc(w.meaning)}</small></button><button class="mark" data-action="favorite" data-id="${esc(w.id)}" aria-label="收藏 ${esc(w.word)}">${state.favorites.includes(w.id)?'★':'☆'}</button></div>`).join('')}</div>`}<div class="aside-box"><b>本章学习进度</b><span>${s.words.filter(w=>state.words[w.id]?.stage>0).length} / ${s.words.length} 词已学习</span></div></aside></div>`;applyPreferences();};
wordModal=function(id){let w=getWord(id);const story=getStory(location.hash.split('/')[1]);if(story)w={...w,...story.words.find(x=>x.id===id)};if(!w)return;selectedWord=id;const p=state.words[id];const related=(w.storyIds||[w.storyId]).map(getStory).filter(Boolean);document.getElementById('word-content').innerHTML=`<div class="dialog-inner"><div class="dialog-top"><h2 id="word-title" class="english-title">${esc(w.word)}</h2><button class="close-button" data-action="close-word" aria-label="关闭释义">×</button></div><p class="phonetic">${w.ukphone?'英 /'+esc(w.ukphone)+'/':''} ${w.usphone?'美 /'+esc(w.usphone)+'/':''} <button class="text-link" data-action="speak-word">◖ 发音</button></p>${w.context?`<div class="context-box"><small>先回到中文语境</small><br>${esc(w.context)}</div>`:''}<div class="word-meaning">${esc(w.meaning)}</div>${w.dictionaryMeaning&&w.dictionaryMeaning!==w.meaning?`<details><summary>词典其他释义</summary><p>${esc(w.dictionaryMeaning)}</p></details>`:''}${w.example?`<div class="word-example" lang="en">${esc(w.example)}</div>`:''}${w.phrase?`<p>搭配：${esc(w.phrase)}</p>`:''}${related.length?`<details class="related-stories"><summary>在 ${related.length} 篇故事里遇见这个词</summary><div class="related-story-links">${related.map(s=>`<a href="#story/${s.id}">${esc(s.title)} ↗</a>`).join('')}</div></details>`:''}<label class="note-label" for="word-note">我的中文联想</label><textarea id="word-note" maxlength="500" placeholder="用自己的话记录这个画面">${esc(state.notes[id]||'')}</textarea><div class="word-source">${esc(w.source)}${p?` · 复习日期 ${esc(p.due)}`:''}</div><div class="dialog-buttons"><button class="button compact" data-action="remember-word">我记住了</button><button class="button secondary compact" data-action="forget-word">还不熟</button><button class="button secondary compact" data-action="save-note">保存笔记</button><button class="button secondary compact" data-action="favorite" data-id="${esc(id)}">${state.favorites.includes(id)?'★ 已收藏':'☆ 收藏'}</button></div></div>`;if(!wordDialog.open)wordDialog.showModal();};
startQuiz=function(words,storyId=null){if(!words.length){toast('这个队列暂无单词。');return;}quiz={words:storyId?shuffle(words):shuffle(words).slice(0,12),storyId,index:0,correct:0,wrong:[],mode:'choice',answered:false,choice:'',options:[],finished:false};wordDialog.close();utilityDialog.close();if(location.hash==='#quiz')quizPage();else location.hash='quiz';};
quizPage=function(){if(!quiz){main.innerHTML='<div class="empty-state"><h2>选择一个练习队列</h2><p>刷新页面会结束本轮，已答题目的进度保留。</p><a href="#review" class="button">今日复习</a></div>';return;}if(quiz.finished){quizResult();return;}const w=quiz.words[quiz.index];if(!quiz.options.length)quiz.options=shuffle([w,...shuffle(allWords().filter(x=>x.id!==w.id)).slice(0,3)]);const surface=w.surface||w.word;const blank=w.example?maskSurface(w.example,surface):'';main.innerHTML=`<div class="reader-top"><a href="#review" class="back-link">← 退出练习</a><div class="mode-buttons">${[['choice','中文选词'],['spelling','拼写回忆'],['listening','听音拼写']].map(([mode,label])=>`<button data-mode="${mode}" class="${quiz.mode===mode?'active':''}" ${quiz.answered?'disabled':''}>${label}</button>`).join('')}</div></div><section class="review-card" style="max-width:850px;margin:auto"><div class="practice-label">以下为原创 CET-style 仿真模拟训练。</div><div class="quiz-top"><span>${quiz.mode==='listening'?'听发音，写英文':'先理解，再提取英文原形'}</span><span>${quiz.index+1} / ${quiz.words.length}</span></div><div class="quiz-bar"><span style="width:${quiz.index/quiz.words.length*100}%"></span></div>${quiz.mode==='listening'?`<button class="button secondary" data-action="speak" data-id="${esc(w.id)}">◖ 播放单词</button>`:`${w.context?`<div class="context-box">${esc(w.context)}</div>`:''}<div class="quiz-cn">${esc(w.meaning)}</div>${blank?`<p class="quiz-sentence" lang="en">${esc(blank)}</p>`:''}`}${quiz.mode==='choice'?`<div class="answer-grid">${quiz.options.map((o,i)=>`<button class="answer ${quiz.answered?(o.id===w.id?'correct':quiz.choice===o.id?'wrong':''):''}" data-answer="${esc(o.id)}" ${quiz.answered?'disabled':''}><b>${'ABCD'[i]}</b>${esc(o.word)}</button>`).join('')}</div>`:`<form id="spelling-form"><label for="spell-input">英文单词原形</label><input class="spelling-input" id="spell-input" autocomplete="off" autocapitalize="off" spellcheck="false" value="${quiz.answered?esc(quiz.choice):''}" ${quiz.answered?'disabled':''}><button type="submit" class="button compact" ${quiz.answered?'disabled':''}>检查答案</button></form>`}${quiz.answered?`<div class="answer-feedback ${quiz.choice===w.id?'good':'bad'}"><b>${quiz.choice===w.id?'回答正确':'本题答错，已加入错词队列'}</b><span>${esc(w.word)} · ${esc(w.meaning)}</span>${w.example?`<span>${esc(w.example)}</span>`:''}</div><button class="button" data-action="next-question">${quiz.index+1===quiz.words.length?'查看结果':'下一题'} →</button>`:''}</section>`;};
const oldReview=review;
review=function(){oldReview();main.querySelector('.review-options').insertAdjacentHTML('beforeend',`<button class="button secondary" data-action="mistake-quiz">错词重练 (${Object.keys(state.mistakes).length})</button><button class="button secondary" data-action="favorite-quiz">收藏专练 (${state.favorites.length})</button>`);};
notebook=function(){main.innerHTML=`<div class="page-heading"><div class="eyebrow">CET-6 · COMPLETE REFERENCE BANK</div><h1>每个词，都能找到。</h1><p>${COVERAGE.reference} 个参考词表词条 + ${BUILTIN_WORDS.length-COVERAGE.reference} 个补充词 · ${state.custom.length} 个自添词</p></div>${coveragePanel()}<div class="notebook-top"><label class="search"><span>⌕</span><input id="notebook-search" type="search" aria-label="搜索词库" placeholder="英文 / 中文释义" value="${esc(notebookSearch)}"></label><div class="notebook-actions"><button class="button secondary compact" data-action="backup">备份进度</button><button class="button secondary compact" data-action="restore">恢复备份</button><button class="button secondary compact" data-action="export-vocab">导出收藏 CSV</button><button class="button compact" data-action="import-words">添加生词</button></div></div><div class="filters">${[['all','全部'],['cet6','六级'],['cet4','四级基础'],['story','有故事语境'],['uncovered','尚无故事语境'],['favorite','收藏'],['mistakes','错词'],['due','到期'],['new','未学'],['learned','已学'],['custom','自添']].map(([id,label])=>`<button class="filter ${notebookFilter===id?'active':''}" data-notebook="${id}">${label}</button>`).join('')}</div><div id="word-list"></div><p class="practice-label">进度保存在当前浏览器；移动网页文件或换设备前，建议导出备份。</p><input type="file" id="backup-input" accept=".json,application/json" hidden>`;renderWordList();};
renderWordList=function(){const list=allWords().filter(w=>{const p=state.words[w.id];const match=notebookFilter==='all'||notebookFilter==='cet6'&&w.levels?.includes('六级')||notebookFilter==='cet4'&&w.levels?.includes('四级基础')||notebookFilter==='story'&&w.storyId||notebookFilter==='uncovered'&&!w.storyId||notebookFilter==='favorite'&&state.favorites.includes(w.id)||notebookFilter==='mistakes'&&state.mistakes[w.id]||notebookFilter==='due'&&p?.due<=today()||notebookFilter==='new'&&!p||notebookFilter==='learned'&&p?.stage>0||notebookFilter==='custom'&&w.source==='我的生词';return match&&(!notebookSearch||`${w.word} ${w.meaning} ${w.dictionaryMeaning||''}`.toLowerCase().includes(notebookSearch.toLowerCase()));});document.getElementById('word-list').innerHTML=`<div class="library-caption"><span>匹配 ${list.length} 个词</span><button data-action="filtered-quiz">练习当前筛选 →</button></div>${list.length?`<div class="word-table-wrap"><table class="word-table"><thead><tr><th>英文</th><th>中文释义</th><th>语境 / 来源</th><th>状态</th><th>操作</th></tr></thead><tbody>${list.slice(0,notebookLimit).map(w=>{const [cl,label]=statusFor(w);return `<tr><td><button class="table-word" data-word="${esc(w.id)}">${esc(w.word)}</button><div class="phonetic">${esc(w.ukphone||'')}</div></td><td>${esc(w.meaning)}</td><td>${w.storyId?`<a href="#story/${w.storyId}">${esc(w.source)} ↗</a>`:esc(w.source)}</td><td><span class="word-status ${cl}">${label}</span></td><td><button class="icon-button" data-action="speak" data-id="${esc(w.id)}" aria-label="朗读 ${esc(w.word)}">◖</button><button class="icon-button" data-action="favorite" data-id="${esc(w.id)}" aria-label="收藏 ${esc(w.word)}">${state.favorites.includes(w.id)?'★':'☆'}</button></td></tr>`;}).join('')}</tbody></table></div>${list.length>notebookLimit?'<button class="button secondary load-more" data-action="more-words">再显示 40 个词</button>':''}`:'<div class="empty-state"><h2>没有匹配的词汇</h2><p>试试其他筛选条件。</p></div>'}`;window.currentWordFilter=list;};
function units(id){const size=20,sorted=[...DICTIONARY_WORDS].sort((a,b)=>a.id.localeCompare(b.id)),total=Math.ceil(sorted.length/size);if(!id){main.innerHTML=`<div class="page-heading"><div class="eyebrow">ALL WORDS · ${total} UNITS</div><h1>完整词库，分成每天的一小份。</h1><p>每单元 20 词，按字母排序。这里是词汇研读单元，原创短篇在故事书架。</p></div><div class="study-unit-grid">${Array.from({length:total},(_,i)=>{const words=sorted.slice(i*size,(i+1)*size);return `<a href="#units/${i+1}">单元 ${String(i+1).padStart(3,'0')}<small>${words[0].word} — ${words[words.length-1].word}</small><small>${words.filter(w=>state.words[w.id]?.stage>0).length} / ${words.length} 已学</small></a>`;}).join('')}</div>`;return;}const n=Number(id);if(!Number.isInteger(n)||n<1||n>total){location.hash='units';return;}const words=sorted.slice((n-1)*size,n*size).map(w=>getWord(w.id));window.unitWords=words;main.innerHTML=`<div class="page-heading"><a href="#units">← 单元目录</a><h1>单元 ${String(n).padStart(3,'0')}</h1><p>先看中文，再点击词卡展开英文，尝试回忆后再核对。</p><button class="button" data-action="unit-quiz">练习本单元 →</button></div><div class="progress-grid">${words.map(w=>`<div class="progress-card"><p>${esc(w.dictionaryMeaning||w.meaning)}</p><details><summary>揭开英文</summary><p><button class="table-word" data-word="${esc(w.id)}">${esc(w.word)}</button></p><p class="phonetic">${esc(w.ukphone||'')}</p>${w.storyId?`<a href="#story/${w.storyId}">回到「${esc(w.source)}」 ↗</a>`:''}</details></div>`).join('')}</div><div class="chapter-nav">${n>1?`<a href="#units/${n-1}">← 上一单元</a>`:'<span></span>'}${n<total?`<a href="#units/${n+1}">下一单元 →</a>`:''}</div>`;}
function progress(){const learned=Object.values(state.words).filter(p=>p.stage>0).length;main.innerHTML=`<div class="page-heading"><div class="eyebrow">YOUR READING JOURNEY</div><h1>留下来的，都是走过的路。</h1><p>学习日历、阅读书签和词汇覆盖，一处查看。</p></div><div class="progress-grid"><div class="progress-card"><strong>${state.completed.length}</strong><p>已读短篇 / ${STORIES.length}</p></div><div class="progress-card"><strong>${learned}</strong><p>已学习词汇 / ${allWords().length}</p></div><div class="progress-card"><strong>${streak()}</strong><p>连续学习天数</p></div></div><section class="progress-card"><h2>最近 28 天</h2><div class="activity-grid">${Array.from({length:28},(_,i)=>{const d=afterDays(i-27),n=state.activity[d]?.length||0;return `<div class="activity-cell ${n?'filled':''}" title="${d} · ${n} 词">${d.slice(5)}<span>${n} 词</span></div>`;}).join('')}</div><p>同一天重复学习同一个词，只计入一个词。阅读完成与词汇掌握分别记录。</p></section><div class="section-title"><h2>我的阅读书签</h2></div><div class="story-grid">${state.bookmarks.length?state.bookmarks.map(id=>storyCard(getStory(id))).join(''):'<p>在阅读页点击「加书签」，下次从这里继续。</p>'}</div>${coveragePanel()}`;}
const oldRender=render;
render=function(){const [route,id]=location.hash.slice(1).split('/');if(['progress','units'].includes(route)){wordDialog.close();utilityDialog.close();document.body.classList.remove('focus-mode');if('speechSynthesis'in window)speechSynthesis.cancel();if(route==='progress')progress();else units(id);updateNav();}else oldRender();activeSpeech=null;applyPreferences();};
speak=function(text){if(!('speechSynthesis'in window)){toast('此浏览器没有朗读支持。');return;}if(activeSpeech===text&&speechSynthesis.speaking){speechSynthesis.cancel();activeSpeech=null;toast('朗读已停止');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=state.preferences.rate;activeSpeech=text;u.onend=()=>activeSpeech=null;u.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))toast('语音暂不可用，请检查系统英语语音。');};speechSynthesis.speak(u);};
function savePendingNote(){const el=document.getElementById('word-note');if(wordDialog.open&&el&&selectedWord)state.notes[selectedWord]=el.value.slice(0,500);}
// Capture extension actions before the base click router handles legacy buttons.
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const action=el.dataset.action,id=el.dataset.id;const handled=el.dataset.reading||['more-stories','random-story','bookmark','night','mistake-quiz','favorite-quiz','filtered-quiz','unit-quiz','export-vocab','favorite','read-aloud','remember-word','forget-word'].includes(action);if(!handled)return;e.stopImmediatePropagation();
  if(el.dataset.reading){readingMode=el.dataset.reading;reader(location.hash.split('/')[1]);}
  else if(action==='more-stories'){storyLimit+=12;renderCards();}
  else if(action==='random-story'){const pool=filteredStories();if(pool.length)location.hash='story/'+shuffle(pool)[0].id;}
  else if(action==='bookmark'){state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();reader(id);}
  else if(action==='night'){state.preferences.night=!state.preferences.night;save();applyPreferences();el.textContent=state.preferences.night?'日间纸张':'夜间阅读';}
  else if(action==='favorite'){savePendingNote();state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();if(wordDialog.open)wordModal(id);else if(location.hash==='#notebook')renderWordList();else if(location.hash.startsWith('#story/'))reader(location.hash.split('/')[1]);}
  else if(action==='remember-word'||action==='forget-word'){savePendingNote();record(selectedWord,action==='remember-word');wordDialog.close();render();}
  else if(action==='read-aloud'){const s=getStory(location.hash.split('/')[1]);if(s)speak(s.en.join(' ').replace(/\[\[([^|\]]+)(?:\|([^\]]+))?\]\]/g,(_,a,b)=>b||a));}
  else if(action==='mistake-quiz')startQuiz(allWords().filter(w=>state.mistakes[w.id]));
  else if(action==='favorite-quiz')startQuiz(allWords().filter(w=>state.favorites.includes(w.id)));
  else if(action==='filtered-quiz')startQuiz(window.currentWordFilter||[]);
  else if(action==='unit-quiz'){startQuiz(window.unitWords||[]);if(quiz){quiz.words=shuffle(window.unitWords);if(location.hash==='#quiz')quizPage();}}
  else if(action==='export-vocab'){const cell=t=>'"'+String(t||'').replace(/"/g,'""')+'"',rows=[['word','meaning','context','note'],...allWords().filter(w=>state.favorites.includes(w.id)).map(w=>[w.word,w.meaning,w.context,state.notes[w.id]])];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='wordscene-favorites.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('已导出收藏词表');}
},true);
document.addEventListener('change',e=>{if(e.target.id==='reading-size'){state.preferences.size=Number(e.target.value);save();applyPreferences();}else if(e.target.id==='speech-rate'){state.preferences.rate=Number(e.target.value);save();}},true);
// Restore all v2 features as well as v1 vocabulary progress. Merge, never erase.
document.addEventListener('change',async e=>{if(e.target.id!=='backup-input')return;e.stopImmediatePropagation();const file=e.target.files[0];if(!file)return;try{if(file.size>8000000)throw Error('备份超过 8 MB');const raw=JSON.parse(await readWordsceneBackupFile(file));if(![1,2].includes(raw?.version)||!raw.words||Array.isArray(raw.words)||!Array.isArray(raw.custom))throw Error('不是有效的词间备份');const incoming=cleanState(raw);state.custom=[...new Map([...state.custom,...incoming.custom].map(w=>[w.id,w])).values()].slice(0,1500);state.words={...state.words,...incoming.words};state.skills=mergeSkillRecords(state.skills,incoming.skills);state.listeningChecks=mergeListeningChecks(state.listeningChecks,incoming.listeningChecks);state.training=mergeTrainingRecords(state.training,incoming.training);state.microWork=mergeMicroWork(state.microWork,incoming.microWork);state.serial=mergeSerial(state.serial,incoming.serial);state.userNovels=mergeUserNovels(state.userNovels,incoming.userNovels);state.favorites=[...new Set([...state.favorites,...incoming.favorites])];state.completed=[...new Set([...state.completed,...incoming.completed])];state.bookmarks=[...new Set([...state.bookmarks,...incoming.bookmarks])];state.notes={...state.notes,...incoming.notes};for(const [id,n]of Object.entries(incoming.mistakes))state.mistakes[id]=Math.max(state.mistakes[id]||0,n);for(const [day,ids]of Object.entries(incoming.activity))state.activity[day]=[...new Set([...(state.activity[day]||[]),...ids])];state.goal=incoming.goal;state.preferences=incoming.preferences;state.lastStory=incoming.lastStory;state=cleanState(state);save();applyPreferences();notebook();toast('备份已合并：词汇、笔记、书签、错词与设置均已恢复。');}catch(error){toast('恢复失败：'+error.message);}finally{e.target.value='';}},true);
addWords=function(){const raw=document.getElementById('import-text').value.trim(),error=document.getElementById('import-error');if(!raw){error.textContent='请先输入生词。';return;}const lines=raw.split('\n').filter(l=>l.trim());if(lines.length>200){error.textContent='每次最多 200 行。';return;}const existing=new Set(allWords().map(w=>w.id)),items=[],bad=[];lines.forEach((line,i)=>{const [word,meaning,...example]=line.split('|').map(s=>s.trim());if(!/^[a-z][a-z '-]{0,49}$/i.test(word||'')||!meaning||meaning.length>150){bad.push(i+1);return;}const id=word.toLowerCase();if(!existing.has(id)){items.push({id,word:id,meaning,pos:'自定义',phrase:'',example:example.join(' | ').slice(0,500),source:'我的生词',storyId:null});existing.add(id);}});if(bad.length){error.textContent=`第 ${bad.join('、')} 行格式错误。用 英文 | 中文释义 | 英文例句（可选），释义最多 150 字。`;return;}if(state.custom.length+items.length>1500){error.textContent='自添生词总数不能超过 1500。';return;}state.custom.push(...items);save();utilityDialog.close();notebookFilter='custom';notebook();toast(`已添加 ${items.length} 个生词，重复词已跳过。`);};
// Replace stale about copy without registering a second modal action.
const about=document.getElementById('about-button');
if(about){about.replaceWith(about.cloneNode(true));document.getElementById('about-button').addEventListener('click',()=>utility('内容与词表说明',`<p>${STORIES.length} 篇原创修仙/悬疑短篇，${COVERAGE.reference} 个参考词表词条，${COVERAGE.storyUnique} 个不同故事重点词。</p><p>完整收录 Qwerty Learner 两份四六级词表及 ECDICT 全部 cet4/cet6 标记词。词表并集完整收录，小说尚未逐词覆盖整个词库；覆盖率在词库页可查。</p><p>不同出版社的六级词表口径并不完全一致。本地词表下载于 ${(typeof DICTIONARY_META!=='undefined'&&DICTIONARY_META&&DICTIONARY_META.retrieved)||'本地词表'}，来源与许可可查看 <a href="SOURCES.md" target="_blank" rel="noopener">SOURCES.md ↗</a>。</p><p>进度与笔记仅保存在当前浏览器；可导出 JSON 备份。每日目标只按标记或答题过的不同词计算。</p>`));}
const goal=document.getElementById('goal-button');
if(goal){goal.replaceWith(goal.cloneNode(true));document.getElementById('goal-button').addEventListener('click',()=>utility('每日学习目标',`<p>标记词汇或提交答案才计入每日目标；阅读完成单独记录。</p><label for="goal-select">每天学习词数</label><select id="goal-select">${[10,20,30,50].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} 词</option>`).join('')}</select><button class="button" data-action="save-goal">保存目标</button>`));}
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#story/')){readingMode='cn';reader(location.hash.split('/')[1]);}});
